function config({baseUrl,categoryId}) {
  if(typeof baseUrl!=='string'||!/^https?:\/\/[^\/?#@\s]+(?:\/[^?#\s]*)?$/i.test(baseUrl)||baseUrl.includes('YOUR_'))throw Error('Configure a Mealie base URL without credentials');
  if(typeof categoryId!=='string'||categoryId.includes('YOUR_'))throw Error('Configure a Mealie category ID or leave it empty');
  const base=baseUrl.replace(/\/+$/,'');return {base,readUrl:base+'/api/recipes?perPage=100'+(categoryId.trim()?'&categories='+encodeURIComponent(categoryId.trim()):''),postUrl:base+'/api/households/mealplans'};
}

return [{json:{...config({baseUrl:'https://YOUR_MEALIE_SERVER',categoryId:'YOUR_CATEGORY_ID'}),count:5,offset:3}}];

function plan({body,count,offset}) {
  if(!body||!Array.isArray(body.items))throw Error('Mealie did not return a recipe list');
  const items=body.items;
  if(!Number.isInteger(count)||count<1||count>100||!Number.isInteger(offset)||offset<0||offset>365)throw Error('Configure a recipe count from 1 to 100 and a day offset from 0 to 365');
  if(items.length<count)throw Error('Not enough recipes for the requested meal count');
  if(items.some(x=>!x||typeof x.id!=='string'||!x.id||typeof x.name!=='string'))throw Error('A recipe is missing its ID or name');
  const ids=items.map(x=>x.id);if(new Set(ids).size!==ids.length)throw Error('Recipe IDs must be unique');
  const shuffled=[...items];for(let i=shuffled.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[shuffled[i],shuffled[j]]=[shuffled[j],shuffled[i]]}
  const today=new Date();today.setUTCHours(0,0,0,0);return {plans:shuffled.slice(0,count).map((r,i)=>{const d=new Date(today);d.setUTCDate(d.getUTCDate()+offset+i);return {date:d.toISOString().slice(0,10),entryType:'dinner',recipeId:r.id,name:r.name}})};
}

const cfg=$('Configure Mealie').first().json;return plan({body:$input.first().json,count:cfg.count,offset:cfg.offset}).plans.map(x=>({json:x}));
